fn glyph_of(v: i32) -> i32 {
    match v {
        1 => 33,
        2 => 63,
        3 => 43,
        _ => 79,
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x101018);
    if host::display::state_get(0) == 0 {
        host::mp::auto(7);
        host::display::state_set(0, 1);
    }
    if host::mp::connected() == 0 {
        host::display::draw_string(170, 240, "CONNECTING", 0x8899aa, 2);
    } else {
        let down: i32 = host::display::pointer_down();
        let prev: i32 = host::display::state_get(1);
        host::display::state_set(1, down);
        if down == 1 && prev == 0 {
            let mut v: i32 = 1;
            if host::display::pointer_x() >= w / 2 {
                v = v + 1;
            }
            if host::display::pointer_y() >= h / 2 {
                v = v + 2;
            }
            host::mp::send(v);
        }
        let mut evs: i32 = host::mp::event_count();
        while evs > 0 {
            let got: i32 = host::mp::event_next();
            let head: i32 = host::display::state_get(10);
            host::display::state_set(11 + head * 2, glyph_of(got));
            host::display::state_set(12 + head * 2, 90);
            host::display::state_set(10, (head + 1) % 4);
            evs = evs - 1;
        }
        host::display::draw_line(w / 2, 0, w / 2, h, 0x222833);
        host::display::draw_line(0, h / 2, w, h / 2, 0x222833);
        host::display::draw_char(118, 118, 33, 0x333344, 3);
        host::display::draw_char(374, 118, 63, 0x333344, 3);
        host::display::draw_char(118, 374, 43, 0x333344, 3);
        host::display::draw_char(374, 374, 79, 0x333344, 3);
        let mut i: i32 = 0;
        while i < 4 {
            let timer: i32 = host::display::state_get(12 + i * 2);
            if timer > 0 {
                let mut col: i32 = 0xffffff;
                if timer < 30 {
                    col = 0x555566;
                }
                host::display::draw_char(60 + i * 110, 220, host::display::state_get(11 + i * 2), col, 8);
                host::display::state_set(12 + i * 2, timer - 1);
            }
            i = i + 1;
        }
        host::display::draw_string(8, 8, "TAP A QUADRANT TO EMOTE", 0x556677, 1);
    }
    host::display::present();
}
